Let $\varepsilon, \sigma>0$, with $\sigma \leq \frac{1}{\sqrt{\varepsilon d}}$, and consider any $C^2$-smooth  uniformly bounded function $f: \mathbb{R}^d \times \mathbb{R}^d \rightarrow \mathbb{R}$ with Lipschitz Hessian. 

 Then there exists a point $(x^\star, y^\star) \in \mathbb{R}^d \times \mathbb{R}^d$  which is an ($\varepsilon^\star, \sigma)$-greedy adversarial equilibrium for $f$, for some  $\varepsilon^\star \leq \varepsilon$.

Moreover, there exists an algorithm which, given access to oracles for the value of a $C^2$-smooth function $f: \mathbb{R}^d \times \mathbb{R}^d \rightarrow [-b,b]$, and to oracles for $\nabla_y f$ and $\nabla^2_y f$, where $f$ has $L_{}$-Lipschitz Hessian for some $b, L_{} >0$, and numbers $\varepsilon, \sigma \geq 0$, with probability at least $\frac{9}{10}$ generates a  point $(x^\star,y^\star) \in \mathbb{R}^{d} \times \mathbb{R}^{d}$ which is an $(\varepsilon^\star, \sigma)$-greedy adversarial equilibrium for $f$, for some  $\varepsilon^\star \leq \varepsilon$. 

 Moreover, this algorithm takes a number of gradient, Hessian, and function evaluations which is polynomial in $\frac{1}{\varepsilon}, d, b, L_{}, \frac{1}{\sigma}$.

\caption{Computing a greedy adversarial equilibrium }

\KwIn{Oracle for a function $f: \mathbb{R}^d \times \mathbb{R}^d \rightarrow \mathbb{R}$, and oracles for the gradient $\nabla_yf$ and Hessian $\nabla_y^2f$. $\sigma,\varepsilon >0$}

\KwHyperparameters{\, \, $\eta, \gamma_1, \mathcal{I}_2, \delta, \mathcal{I}_3, \mathcal{I}_4, \alpha,  \varepsilon_0$}


 Initialize $(x_0, y_0) \leftarrow (0, 0)$

 Set $x_1 \leftarrow x_0$. 

Run Algorithm alg:InnerMaxLoop with inputs $\mathsf{x} \leftarrow x_1$,  $\mathsf{y}^0  \leftarrow y_0$,  $\varepsilon' \leftarrow \varepsilon_{0}(1+\delta)$. 

Set $y_1 \leftarrow \mathsf{y}_{\mathrm{LocalMax}}$ to be the output $\mathsf{y}_{\mathrm{LocalMax}}$ of Algorithm alg:InnerMaxLoop.     

Set $h^0 \leftarrow f(x_1, y_1)$


  Set $\mathsf{Stop}\leftarrow \mathsf{False}$, \, $i \leftarrow 0$\\

\While{$\mathsf{Stop}=\mathsf{False}$}{ 

Set $i \leftarrow i+1$, \, \, \,

   $\mathsf{NoProgress} \leftarrow \mathsf{True}$, \, \, \,

 Set $\varepsilon_{i} \leftarrow \varepsilon_{i-1}(1+\delta)^2$

 Set $X_0 \leftarrow x_{i}$


\For{$j=1$ to $\mathcal{I}_3$}{

\If{$\mathsf{NoProgress} = \mathsf{True}$}{


Set $\zeta_{i j} \sim N(0,I_d)$


Run Algorithm alg:InnerMaxLoop with inputs $\mathsf{x} \leftarrow x_{i} + \sigma \zeta_{i j}$,  $\mathsf{y}^0 \leftarrow y_{i}$, and $\varepsilon' \leftarrow \varepsilon_{i}(1+\delta)$.


Set $\mathcal{Y} \leftarrow \mathsf{y}_{\mathrm{LocalMax}}$ to be the output $\mathsf{y}_{\mathrm{LocalMax}}$ of Algorithm alg:InnerMaxLoop.     


\If{$f(x_{i} + \sigma \zeta_{i j}, \mathcal{Y}) \leq f(x_{i}, y_{i}) - \gamma_1$}{ 

Set $x_{i+1} \leftarrow x_{i} + \sigma \zeta_{i j}$

Set $y_{i+1} \leftarrow \mathcal{Y}$,  


Set $h^0 \leftarrow f(x_{i}, y_{i})$

Set  $i \leftarrow i+1$, \, \, \, $\mathsf{NoProgress} \leftarrow \mathsf{False}$,


}

}

}  

\For{$j=1$ to $\mathcal{I}_4$ }{

\If{$\mathsf{NoProgress} = \mathsf{True}$}{

\For{$k = 1$ to $\mathcal{I}_2$}{ 

Set $u \sim N(0,I_d)$


Run Algorithm alg:InnerMaxLoop with inputs $\mathsf{x} \leftarrow X_{k-1} + \sigma u$,  $\mathsf{y}^0 \leftarrow y_{i}$,  $\varepsilon' \leftarrow \varepsilon_{i}(1+\delta)$.

Set $\mathcal{Y} \leftarrow \mathsf{y}_{\mathrm{LocalMax}}$ to be the output $\mathsf{y}_{\mathrm{LocalMax}}$ of Algorithm alg:InnerMaxLoop.     


Set $h^{k} = \min(f(X_{k-1} + \sigma u, \mathcal{Y}), f(x_{i}, y_{i}))$ 

Set $\Gamma_{k} = (h^{k} - h^{k-1}) \frac{1}{\sigma} u$ 

Set $\xi \sim N(0,I_d)$, \, \, \,

Set $X_{k} \leftarrow X_{k-1} - \eta \Gamma_{k} + \alpha \xi$   

}  

Run Algorithm alg:InnerMaxLoop with inputs $\mathsf{x} \leftarrow X_{k}$, $\mathsf{y}^0 \leftarrow y_{i}$, and $\varepsilon' \leftarrow \varepsilon_{i}(1+\delta)$.

Set $\mathcal{Y} \leftarrow \mathsf{y}_{\mathrm{LocalMax}}$ to be the output $\mathsf{y}_{\mathrm{LocalMax}}$ of Algorithm alg:InnerMaxLoop.  

\If{$f(X_{k}, \mathcal{Y}) \leq f(X_0, y_{i}) - \gamma_1 $}{ 

Set $x_{i+1} \leftarrow X_{k}$

Set $y_{i+1} \leftarrow \mathcal{Y}$,  

Set $h^0 \leftarrow f(x_{i}, y_{i})$, \, \, \,

Set  $i \leftarrow i+1$, \,  \, \,

$\mathsf{NoProgress} \leftarrow \mathsf{False}$


} 

}

} 

\If{$\mathsf{NoProgress} = \mathsf{True}$}{

Set $\mathsf{Stop} = \mathsf{True}$ 

}

}


\Return{$i^\star \leftarrow i$,  $\varepsilon^\star \leftarrow \varepsilon_{i^\star}$, and $(x^\star, y^\star) \leftarrow (x_{i^\star}, y_{i^\star})$}

Consider any $\varepsilon>0$.  

Suppose that $\sigma \leq \frac{1}{\sqrt{\varepsilon d}}$ and that for some point $(x^\star, y^\star) \in \mathbb{R}^d \times \mathbb{R}^d$ we have

\begin{equation}\qquad h_\varepsilon(x,y) \leq g_\varepsilon(x,y) \qquad \forall x,y \in \mathbb{R}^d \qquad \textrm{(lower bound)},  \end{equation}

\begin{equation} \quad h_\varepsilon(x^\star,y^\star) = g_\varepsilon(x^\star,y^\star)  \qquad \qquad \textrm{(fixed-point  property)}, \end{equation}

\begin{equation}   \qquad \quad \mathbb{E}[\|\mathcal{H}_\varepsilon^{x^\star}(x^\star,y^\star)\|] \leq \frac{1}{8000}  \frac{\sigma^{14} \varepsilon^{1.5}}{b^2} \ \  \textrm{(low SG)}, \end{equation}


\begin{equation}    \|\nabla_x \mathfrak{h}_{\varepsilon, \sigma}^{x^\star}(x^\star, y^\star)\| \leq \frac{\varepsilon^2\sigma^7}{8000b} \ \ \textrm{(1st-order stationarity for $\mathfrak{h}$) },
\end{equation}


\begin{equation} \lambda_{\mathrm{min}}(\nabla^2_{{x}} \mathfrak{h}_{\varepsilon, \sigma}^{x^\star}(x^\star, y^\star)) \geq - \frac{\sqrt{\varepsilon} }{5} \ \ \textrm{(2nd-order stationarity)}. \end{equation}

Then

\begin{equs} 
\|\nabla_x \mathfrak{g}_{\varepsilon, \sigma}^{x^\star}(x^\star, y^\star)\| \leq \varepsilon \ \ {\textrm and}
\end{equs}
\begin{equs} 
 \lambda_{\mathrm{min}}(\nabla^2_{{x}} \mathfrak{g}_{\varepsilon, \sigma}^{x^\star}(x^\star, y^\star)) \geq - \sqrt{\varepsilon}.
\end{equs}

\begin{equs} 
  h_{\varepsilon^{\circ}} (x,y) \leq g_{\varepsilon^{\circ}}(x,y), \qquad \forall x,y \in \mathbb{R}^d,  \forall \varepsilon^{\circ} > 0.
  \end{equs}

With probability at least $1-\omega$ the stochastic gradient $\mathcal{H}_{\varepsilon_{i^\star}}$ at the outputs $(x^\star, y^\star)$ of Algorithm alg:LocalMin-max satisfies
\begin{equs}
\mathbb{E}\left[\left\|\mathcal{H}^{x^\star}_{\varepsilon_{i^\star}}(x^\star, y^\star)\right\| \, \bigg | \, (x^\star, y^\star) \right] \leq 10 b \gamma_1 \sqrt{d}\sigma^{-1} \log\frac{2}{\gamma_1}.
\end{equs}

The output  $\mathsf{y}_{\mathrm{LocalMax}}$ of Algorithm alg:InnerMaxLoop with inputs  $\mathsf{x}, \mathsf{y}^0, \varepsilon'$ satisfies
\begin{equation}
\|\nabla_y f(\mathsf{x}, \mathsf{y}_{\mathrm{LocalMax}})\| \leq  \varepsilon'
\end{equation}
and
\begin{equation}
\lambda_{\mathrm{max}}( \nabla^2_{{y}} f(\mathsf{x}, \mathsf{y}_{\mathrm{LocalMax}})) \leq \sqrt{L_{} \varepsilon'}.
\end{equation}

\noindent In particular, this implies that the output $(x^\star, y^\star)$ of Algorithm alg:LocalMin-max satisfies
\begin{equation} 
\|\nabla_y f(x^\star, y^\star)\| \leq  \varepsilon_{i^\star},
\end{equation}
and
\begin{equation} 
\lambda_{\mathrm{max}}( \nabla^2_{{y}} f(x^\star, y^\star)) \leq \sqrt{L_{}  \varepsilon_{i^\star}}.
\end{equation}

Algorithm alg:LocalMin-max terminates after at most  $i^\star = O\left(\frac{b}{\gamma_1}\right)$ iterations, and thus takes at most $O\left(\frac{b}{\gamma_1}  \times  (\mathcal{I}_2 \mathcal{I}_4+ \mathcal{I}_3) \times \frac{b}{ \mu_1 \mu_3^2 L_{}}\right)$ gradient, Hessian, and function evaluations.

\caption{Computing a greedy adversarial equilibrium }

\KwIn{Oracle for a function $f: \mathbb{R}^d \times \mathbb{R}^d \rightarrow \mathbb{R}$, and oracles for the gradient $\nabla_yf$ and Hessian $\nabla_y^2f$. $\sigma,\varepsilon >0$}

\KwHyperparameters{\, \, $\eta, \gamma_1, \mathcal{I}_2, \delta, \mathcal{I}_3, \mathcal{I}_4, \alpha,  \varepsilon_0$}


 Initialize $(x_0, y_0) \leftarrow (0, 0)$

 Set $x_1 \leftarrow x_0$. 

Run Algorithm alg:InnerMaxLoop with inputs $\mathsf{x} \leftarrow x_1$,  $\mathsf{y}^0  \leftarrow y_0$,  $\varepsilon' \leftarrow \varepsilon_{0}(1+\delta)$. 

Set $y_1 \leftarrow \mathsf{y}_{\mathrm{LocalMax}}$ to be the output $\mathsf{y}_{\mathrm{LocalMax}}$ of Algorithm alg:InnerMaxLoop.     

Set $h^0 \leftarrow f(x_1, y_1)$


  Set $\mathsf{Stop}\leftarrow \mathsf{False}$, \, $i \leftarrow 0$\\

\While{$\mathsf{Stop}=\mathsf{False}$}{ 

Set $i \leftarrow i+1$, \, \, \,

   $\mathsf{NoProgress} \leftarrow \mathsf{True}$, \, \, \,

 Set $\varepsilon_{i} \leftarrow \varepsilon_{i-1}(1+\delta)^2$

 Set $X_0 \leftarrow x_{i}$


\For{$j=1$ to $\mathcal{I}_3$}{

\If{$\mathsf{NoProgress} = \mathsf{True}$}{


Set $\zeta_{i j} \sim N(0,I_d)$


Run Algorithm alg:InnerMaxLoop with inputs $\mathsf{x} \leftarrow x_{i} + \sigma \zeta_{i j}$,  $\mathsf{y}^0 \leftarrow y_{i}$, and $\varepsilon' \leftarrow \varepsilon_{i}(1+\delta)$.


Set $\mathcal{Y} \leftarrow \mathsf{y}_{\mathrm{LocalMax}}$ to be the output $\mathsf{y}_{\mathrm{LocalMax}}$ of Algorithm alg:InnerMaxLoop.     


\If{$f(x_{i} + \sigma \zeta_{i j}, \mathcal{Y}) \leq f(x_{i}, y_{i}) - \gamma_1$}{ 

Set $x_{i+1} \leftarrow x_{i} + \sigma \zeta_{i j}$

Set $y_{i+1} \leftarrow \mathcal{Y}$,  


Set $h^0 \leftarrow f(x_{i}, y_{i})$

Set  $i \leftarrow i+1$, \, \, \, $\mathsf{NoProgress} \leftarrow \mathsf{False}$,


}

}

}  

\For{$j=1$ to $\mathcal{I}_4$ }{

\If{$\mathsf{NoProgress} = \mathsf{True}$}{

\For{$k = 1$ to $\mathcal{I}_2$}{ 

Set $u \sim N(0,I_d)$


Run Algorithm alg:InnerMaxLoop with inputs $\mathsf{x} \leftarrow X_{k-1} + \sigma u$,  $\mathsf{y}^0 \leftarrow y_{i}$,  $\varepsilon' \leftarrow \varepsilon_{i}(1+\delta)$.

Set $\mathcal{Y} \leftarrow \mathsf{y}_{\mathrm{LocalMax}}$ to be the output $\mathsf{y}_{\mathrm{LocalMax}}$ of Algorithm alg:InnerMaxLoop.     


Set $h^{k} = \min(f(X_{k-1} + \sigma u, \mathcal{Y}), f(x_{i}, y_{i}))$ 

Set $\Gamma_{k} = (h^{k} - h^{k-1}) \frac{1}{\sigma} u$ 

Set $\xi \sim N(0,I_d)$, \, \, \,

Set $X_{k} \leftarrow X_{k-1} - \eta \Gamma_{k} + \alpha \xi$   

}  

Run Algorithm alg:InnerMaxLoop with inputs $\mathsf{x} \leftarrow X_{k}$, $\mathsf{y}^0 \leftarrow y_{i}$, and $\varepsilon' \leftarrow \varepsilon_{i}(1+\delta)$.

Set $\mathcal{Y} \leftarrow \mathsf{y}_{\mathrm{LocalMax}}$ to be the output $\mathsf{y}_{\mathrm{LocalMax}}$ of Algorithm alg:InnerMaxLoop.  

\If{$f(X_{k}, \mathcal{Y}) \leq f(X_0, y_{i}) - \gamma_1 $}{ 

Set $x_{i+1} \leftarrow X_{k}$

Set $y_{i+1} \leftarrow \mathcal{Y}$,  

Set $h^0 \leftarrow f(x_{i}, y_{i})$, \, \, \,

Set  $i \leftarrow i+1$, \,  \, \,

$\mathsf{NoProgress} \leftarrow \mathsf{False}$


} 

}

} 

\If{$\mathsf{NoProgress} = \mathsf{True}$}{

Set $\mathsf{Stop} = \mathsf{True}$ 

}

}


\Return{$i^\star \leftarrow i$,  $\varepsilon^\star \leftarrow \varepsilon_{i^\star}$, and $(x^\star, y^\star) \leftarrow (x_{i^\star}, y_{i^\star})$}

With probability at least $1-\omega$ the stochastic gradient $\mathcal{H}_{\varepsilon_{i^\star}}$ at the outputs $(x^\star, y^\star)$ of Algorithm alg:LocalMin-max satisfies
\begin{equs}
\mathbb{E}\left[\left\|\mathcal{H}^{x^\star}_{\varepsilon_{i^\star}}(x^\star, y^\star)\right\| \, \bigg | \, (x^\star, y^\star) \right] \leq 10 b \gamma_1 \sqrt{d}\sigma^{-1} \log\frac{2}{\gamma_1}.
\end{equs}

With probability at least $1-2\omega$, we have that
\begin{equs} 
 \lambda_{\mathrm{min}}\left(\nabla^2_{{x}} \mathfrak{h}_{\varepsilon_{i^\star}, \sigma}^{x^\star}(x^\star, y^\star) \right) \geq - \frac{1}{5}\sqrt{\varepsilon_{i^\star}}.
 \end{equs}

The path consisting of the line segments  $[\mathsf{y}^{\ell}, \mathsf{y}^{\ell+1}]$ formed by the points $\mathsf{y}^{\ell}$ computed by Algorithm alg:InnerMaxLoop is a $\frac{1}{1+\delta}\varepsilon'$-greedy path.

\caption{Computing a greedy path }

\KwIn{Oracles for the value of a function $f: \mathbb{R}^d \times \mathbb{R}^d \rightarrow \mathbb{R}$, the gradient $\nabla_yf$ and the Hessian $\nabla_y^2f$}

\KwIn{$\mathsf{x}, \mathsf{y}^0, \varepsilon'$} 

\KwHyperparameters{$\delta, \mu_1, \mu_3, \mu_4$}

Set $\ell \leftarrow 0$,  $\mathsf{Stopy}  \leftarrow \textrm{False}$

\While{$\mathsf{Stopy} = \mathsf{False}$}{ 

\uIf{$\| \nabla_yf(\mathsf{x}, \mathsf{y}^{\ell})\| > \varepsilon'$}{ 

 Set $\mathsf{y}^{\ell+1} \leftarrow \mathsf{y}^{\ell} + \mu_1 \nabla_yf(\mathsf{x},\mathsf{y}^{\ell})$  

   Set $\ell \leftarrow \ell+1$} 

\Else{

Compute an eigenvalue-eigenvector pair $(\lambda, v)$ of $\nabla^2_{{y}}f(\mathsf{x}, \mathsf{y}^{\ell})$, s.t. $\lambda \geq \lambda_{\mathrm{max}}(\nabla^2_{{y}}f(\mathsf{x}, \mathsf{y}^{\ell})) - \mu_4$  

\uIf{$\lambda > \sqrt{L_{} \varepsilon'}$}{  

Set $\mathsf{a} = \mathrm{sign}(\nabla_yf(\mathsf{x},\mathsf{y}^{\ell})^\top v)$

Set $\mathsf{y}^{\ell+1} \leftarrow \mathsf{y}^\ell + \mu_3  \mathsf{a} v$  

 Set $\ell \leftarrow \ell+1$  


\Else{Set $\mathsf{Stopy} = \mathsf{True}$}}



}

}

\Return{$\mathsf{y}_{\mathrm{LocalMax}} \leftarrow \mathsf{y}^{\ell}$}

Recall that $\varepsilon_i = \varepsilon_0 (1+\delta)^{2i}$, and consider the points $(x_i, y_i)$ generated at each iteration $i$ of the While loop in Algorithm alg:LocalMin-max.  Then
\begin{equs} 
   h_{\varepsilon_i} (x_i,y_i) = g_{\varepsilon_i}(x_i,y_i) = f(x_i, y_i), \qquad \forall i \in \mathbb{N}.
\end{equs}

For any $\varepsilon^{\circ}>0$, $ x,y, \hat{x} \in \mathbb{R}^d$, define

$\hat{\Gamma}^{\hat{x}}_{\varepsilon^{\circ}} (x,y) :=  [\mathbbm{h}_{\varepsilon^{\circ}}^{\hat{x}} (x + \sigma u, y) - c]\frac{1}{\sigma} u,$

where  $u \sim N(0,I_d)$, for some $c\geq 0$ independent of $u$ with $|c| \leq b$.

Then

\begin{equs} 
\mathbb{E}[\hat{\Gamma}^{\hat{x}}_{\varepsilon^{\circ}} (x,y)] = \nabla_{{x}} \mathfrak{h}_{\varepsilon^\circ, \sigma}^{\hat{x}}(x,y).
\end{equs}

and, for every $t \geq 0$, we have

\begin{equs} 
\mathbb{P}(\|\hat{\Gamma}^{\hat{x}}_{\varepsilon^{\circ}} (x,y) - \nabla_{{x}} \mathfrak{h}_{\varepsilon^\circ, \sigma}^{\hat{x}}(x,y)\| \geq t) \leq 2\exp\left(-\frac{t^2}{8\left(\frac{2b\sqrt{d}}{\sigma}\right)^2}\right).
\end{equs}
